<template>
  <div class="page-stack">
    <section class="hero compact"><div><span class="eyebrow">SCHEMATIC CONVERSATIONS</span><h1>原理图生成总览</h1><p>汇总 LiteLLM 中的评测与普通会话，并将主 Agent 和 Subagent 组织为完整会话。</p></div></section>

    <el-card shadow="never" class="panel overview-navigation"><el-tabs v-model="pageTab"><el-tab-pane label="全部会话" name="sessions"/><el-tab-pane label="处理过程" name="process"/></el-tabs></el-card>

    <el-card v-show="pageTab==='process'" shadow="never" class="panel scheduler-status"><template #header><div class="section-head"><div><b>定时处理</b><span>每小时整点自动处理上一完整小时的非评测会话</span></div><el-button link type="primary" :loading="schedulerLoading" @click="loadSchedulerStatus">刷新</el-button></div></template><div class="scheduler-grid"><div><span>开关</span><el-tag :type="scheduler?.enabled?'success':'info'">{{scheduler?.enabled?'已启用':'未启用'}}</el-tag></div><div><span>运行状态</span><b>{{scheduler?.running?'调度器运行中':'调度器未运行'}}</b></div><div><span>下次执行</span><b>{{formatTime(scheduler?.next_run_at)}}</b></div><div><span>上次完成</span><b>{{formatTime(scheduler?.last_finished_at)}}</b></div><div><span>处理窗口</span><b>上一完整小时</b></div><div><span>上次结果</span><b>{{schedulerResultLabel}}</b></div></div><p v-if="scheduler?.last_error" class="scheduler-error">{{scheduler.last_error}}</p></el-card>

    <el-card v-show="pageTab==='sessions'" shadow="never" class="panel search-panel">
      <el-form @submit.prevent="search()">
        <div class="primary-search-row">
          <el-input v-model="sessionId" clearable placeholder="输入会话 ID（主会话或 Subagent session_id）" aria-label="会话 ID" @keyup.enter="search()"/>
          <el-input v-model="requestId" clearable placeholder="输入 LiteLLM 请求 ID" aria-label="请求 ID" @keyup.enter="search()"/>
          <el-button native-type="submit" type="primary" :loading="loading">搜索</el-button>
        </div>
        <div class="filter-strip">
          <label><span>时间范围</span><el-select v-model="timeRangePreset"><el-option v-for="item in timeRangeOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select></label>
          <label><span>工号（End User）</span><el-select v-model="endUser" filterable clearable allow-create :loading="filterOptionsLoading" placeholder="输入或选择工号" @visible-change="loadFilterOptions"><el-option v-for="item in filterOptions.end_users" :key="item" :label="item" :value="item"/></el-select></label>
          <label><span>模型</span><el-select v-model="selectedModel" filterable clearable :loading="filterOptionsLoading" placeholder="全部模型" @visible-change="loadFilterOptions"><el-option v-for="item in filterOptions.models" :key="item" :label="item" :value="item"/></el-select></label>
          <label><span>任务分类</span><el-select v-model="taskClassification" clearable placeholder="全部分类"><el-option v-for="item in taskClassificationOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select></label>
          <label class="turn-filter"><span>交互轮次</span><el-button :type="hideSingleTurn?'primary':''" :plain="!hideSingleTurn" @click="toggleSingleTurn">隐藏单轮会话</el-button></label>
        </div>
      </el-form>
      <p class="search-note">当前时间范围：{{timeRangeLabel}}。这里只展示非评测会话，通过“新建评测”产生的会话不会进入本页；数据按根会话分页，一个主 Agent 及其全部 Subagent 不会被拆分。<span v-if="data.scan_truncated"> 当前列表基于时间范围内最近 {{number(data.scanned_interactions)}} 次调用。</span></p>
    </el-card>

    <el-card v-show="pageTab==='sessions'" shadow="never" class="panel overview-board" v-loading="qualityAggregateLoading">
      <div class="overview-metrics"><div><span>匹配会话</span><b>{{number(data.total)}}</b></div><div><span>当前交互</span><b>{{number(pageInteractions)}}</b></div><div><span>当前 Token</span><b>{{number(pageTokens)}}</b></div><div><span>当前 Subagent</span><b>{{number(pageSubagents)}}</b></div></div>
      <div class="quality-summary-head"><div><b>原理图质量累计指标</b><span>基于已完成指标计算的 {{number(qualityAggregate?.quality_session_count||0)}} 个质量会话汇总 · 更新于 {{formatTime(qualityAggregate?.updated_at)}}</span></div><el-button link type="primary" @click="loadQualityAggregate">刷新</el-button></div>
      <div class="quality-summary-grid"><div v-for="item in qualitySummaryCards" :key="item.label"><span>{{item.label}}</span><b>{{item.value}}</b><small>{{item.count}} 个会话有该指标</small></div></div>
    </el-card>

    <el-card v-show="pageTab==='process'" shadow="never" class="panel process-jobs">
      <template #header><div class="section-head"><div><b>分析任务</b><span>先选择任务，再查看该任务包含的全部会话</span></div><el-button link type="primary" :loading="analysisJobsLoading" @click="loadAnalysisJobs">刷新</el-button></div></template>
      <el-table :data="analysisJobs" v-loading="analysisJobsLoading" row-key="job_id" row-class-name="process-row" highlight-current-row @row-click="viewAnalysisJob">
        <el-table-column label="启动时间" width="180"><template #default="{row}">{{formatTime(row.created_at)}}</template></el-table-column>
        <el-table-column label="任务" width="130"><template #default="{row}">{{taskKindLabel(row.task_kind)}}</template></el-table-column>
        <el-table-column label="会话数" width="95" align="right"><template #default="{row}">{{row.total||0}}</template></el-table-column>
        <el-table-column label="完成/失败/取消" width="150" align="right"><template #default="{row}">{{row.completed||0}} / {{row.failed||0}} / {{row.cancelled||0}}</template></el-table-column>
        <el-table-column label="总用时" width="120"><template #default="{row}">{{jobDuration(row)}}</template></el-table-column>
        <el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="jobTag(row.status)">{{jobStatus(row.status)}}</el-tag></template></el-table-column>
        <el-table-column label="任务 ID" min-width="300"><template #default="{row}"><code>{{row.job_id}}</code></template></el-table-column>
        <el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="viewAnalysisJob(row)">查看会话</el-button><el-button v-if="canCancelJob(row)" link type="danger" :loading="cancellingJobId===row.job_id" @click.stop="cancelAnalysisJob(row)">取消</el-button></template></el-table-column>
      </el-table>
      <el-empty v-if="!analysisJobsLoading&&!analysisJobs.length" description="暂无处理任务"/>
    </el-card>

    <el-card v-if="pageTab==='process'&&analysisJob" shadow="never" class="panel task-sessions" v-loading="analysisJobLoading">
      <template #header><div class="section-head"><div><b>{{taskKindLabel(analysisJob.task_kind)}} · 任务会话</b><span>{{analysisJob.job_id}} · 点击会话查看逐步处理详情</span></div><div class="task-session-actions"><el-tag :type="jobTag(analysisJob.status)">{{jobStatus(analysisJob.status)}}</el-tag><el-button v-if="canCancelJob(analysisJob)" link type="danger" :loading="cancellingJobId===analysisJob.job_id" @click="cancelAnalysisJob(analysisJob)">取消任务</el-button></div></div></template>
      <div class="task-progress"><el-progress :percentage="Number(analysisJob.progress||0)" :status="analysisJob.failed?'exception':analysisJob.status==='completed'?'success':undefined"/><span>完成 {{analysisJob.completed||0}} / {{analysisJob.total||0}}，失败 {{analysisJob.failed||0}}，取消 {{analysisJob.cancelled||0}}</span></div>
      <el-table :data="analysisJobSessions" row-key="session_id" row-class-name="process-row" @row-click="openProcessSession">
        <el-table-column label="Session ID" min-width="310"><template #default="{row}"><code>{{row.session_id}}</code></template></el-table-column>
        <el-table-column label="Judge 模型" min-width="180"><template #default="{row}">{{row.assigned_model||'规则处理'}}</template></el-table-column>
        <el-table-column label="开始时间" width="180"><template #default="{row}">{{formatTime(row.started_at)}}</template></el-table-column>
        <el-table-column label="用时" width="110"><template #default="{row}">{{duration(row.duration_ms)}}</template></el-table-column>
        <el-table-column label="步骤" width="80" align="right"><template #default="{row}">{{row.events?.length||0}}</template></el-table-column>
        <el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="jobTag(row.status)">{{jobStatus(row.status)}}</el-tag></template></el-table-column>
        <el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="openProcessSession(row)">处理详情</el-button></template></el-table-column>
      </el-table>
    </el-card>

    <el-card v-show="pageTab==='sessions'" shadow="never" class="panel list-panel">
      <template #header><div class="list-section-head"><div class="list-heading"><b>会话列表</b><span>点击任意会话行查看完整输入、历史、输出和 Subagent 详情</span></div><div class="list-head-actions"><span>已选择 {{selectedConversations.length}} 个会话</span><el-button type="primary" plain :disabled="!canAnalyze" :loading="submittingTask==='classification'" @click="startAnalysis('classification')">任务分类</el-button><el-button type="primary" :disabled="!canAnalyze" :loading="submittingTask==='metrics'" @click="startAnalysis('metrics')">指标计算</el-button><el-button type="warning" plain :disabled="!canAnalyze" :loading="submittingTask==='conversation_judge'" @click="startAnalysis('conversation_judge')">会话 Judge</el-button><el-switch v-model="useQualityJudge" active-text="质量指标启用 Judge"/><el-tag effect="plain">{{data.conversations?.length||0}} 条</el-tag></div></div></template>
      <el-table v-if="data.conversations?.length" :data="data.conversations" v-loading="loading" row-key="root_session_id" row-class-name="conversation-row" @selection-change="selectedConversations=$event" @row-click="openConversation">
        <el-table-column type="selection" width="48"/>
        <el-table-column label="开始时间" width="176" sortable><template #default="{row}">{{formatTime(row.started_at)}}</template></el-table-column>
        <el-table-column label="会话" min-width="250"><template #default="{row}"><div class="session-cell"><b>{{row.root_session_id}}</b><span>{{row.interaction_count||0}} 轮交互</span></div></template></el-table-column>
        <el-table-column label="用户" min-width="145" show-overflow-tooltip><template #default="{row}">{{conversationUser(row)}}</template></el-table-column>
        <el-table-column label="来源" width="100"><template #default="{row}"><el-tag size="small" :type="sourceType(row.source_kind)">{{sourceLabel(row.source_kind)}}</el-tag></template></el-table-column>
        <el-table-column label="任务分类" min-width="175" show-overflow-tooltip><template #default="{row}">{{taskTypeLabel(row.task_type)}}</template></el-table-column>
        <el-table-column label="Agent" width="120"><template #default="{row}">{{row.agent||'未记录'}}</template></el-table-column>
        <el-table-column label="模型" min-width="190" show-overflow-tooltip><template #default="{row}">{{row.models?.join('、')||'未记录'}}</template></el-table-column>
        <el-table-column label="交互" width="82" align="right"><template #default="{row}">{{number(row.interaction_count)}}</template></el-table-column>
        <el-table-column label="Subagent" width="100" align="right"><template #default="{row}">{{number(row.subagent_count)}}</template></el-table-column>
        <el-table-column label="Token" width="105" align="right"><template #default="{row}">{{number(row.total_tokens)}}</template></el-table-column>
        <el-table-column label="总用时" width="105" align="right"><template #default="{row}">{{duration(row.duration_ms)}}</template></el-table-column>
        <el-table-column label="分析状态" min-width="245"><template #default="{row}"><div class="analysis-status"><el-tag size="small" :type="analysisTag(row.classification_status)">分类 {{analysisStatus(row.classification_status)}}</el-tag><el-tag size="small" :type="analysisTag(row.metric_status)">指标 {{analysisStatus(row.metric_status)}}</el-tag><el-tag size="small" :type="analysisTag(row.conversation_judge_status)">Judge {{analysisStatus(row.conversation_judge_status)}}</el-tag></div></template></el-table-column>
        <el-table-column label="操作" width="220" fixed="right"><template #default="{row}"><div class="row-actions"><el-button link type="primary" @click.stop="openConversation(row,'analysis')">查看结果</el-button><el-dropdown trigger="click" @command="kind=>showSavedProcess(row,kind)"><el-button link type="primary" @click.stop>查看过程⌄</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="classification">任务分类</el-dropdown-item><el-dropdown-item command="metrics">指标计算</el-dropdown-item><el-dropdown-item command="conversation_judge">会话 Judge</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column>
      </el-table>
      <el-empty v-else-if="!loading&&hasSearched" description="没有找到匹配的会话"/>
      <el-empty v-else-if="!loading" description="请设置查询条件后点击搜索"/>
      <el-pagination v-if="data.total" v-model:current-page="sessionPage" v-model:page-size="sessionPageSize" background layout="total, sizes, prev, pager, next, jumper" :page-sizes="[20,50,100]" :total="data.total" class="session-pagination" @current-change="loadConversations" @size-change="changeSessionPageSize"/>
    </el-card>

    <el-dialog v-model="detailVisible" width="94%" top="3vh" append-to-body destroy-on-close class="conversation-dialog" @closed="resetDetail">
      <template #header><div class="dialog-title"><div><span class="eyebrow">CONVERSATION DETAIL</span><b>会话详情</b><small>{{detail?.root_session_id||selectedRoot}}</small></div><el-tag v-if="detail" :type="sourceType(detail.source_kind)">{{sourceLabel(detail.source_kind)}}</el-tag></div></template>
      <div v-loading="detailLoading" class="detail-shell">
        <template v-if="detail">
          <div class="detail-metrics"><div><span>起始时间</span><b>{{formatTime(detail.started_at)}}</b></div><div><span>总用时</span><b>{{duration(detail.duration_ms)}}</b></div><div><span>模型交互</span><b>{{number(detail.interaction_count)}}</b></div><div><span>总 Token</span><b>{{number(detail.total_tokens)}}</b></div><div><span>工具调用</span><b>{{number(detail.tool_call_count)}}</b></div><div><span>Subagent</span><b>{{number(detail.subagent_count)}}</b></div></div>
          <el-tabs v-model="detailView" class="detail-tabs">
            <el-tab-pane label="模型交互" name="timeline">
              <div class="agent-session-picker">
                <button :class="{active:selectedSessionId==='all'}" @click="selectedSessionId='all'"><b>全部会话</b><small>{{number(detail.timeline?.length)}} 次调用</small></button>
                <button v-for="(node,index) in detail.sessions" :key="node.session_id" :class="{active:selectedSessionId===node.session_id}" @click="selectedSessionId=node.session_id">
                  <b>{{sessionNodeLabel(node,index)}}</b><small>{{node.interaction_count}} 次调用 · {{node.models?.join('、')||'模型未记录'}}</small><code>{{node.session_id}}</code>
                </button>
              </div>
              <div class="interaction-toolbar"><el-input v-model="interactionKeyword" clearable placeholder="搜索当前 Agent 的提示词、输出、工具或请求 ID"/><span>当前显示 {{filteredInteractions.length}} 轮，按时间顺序排列</span></div>
              <div v-if="filteredInteractions.length" class="turn-list">
                <article v-for="(item,index) in filteredInteractions" :key="item.request_id||index" class="turn-card" @click="openInteraction(item,index)">
                  <header class="turn-title"><span class="sequence">{{index+1}}</span><div><b>{{item.model_group||item.model||'未知模型'}}</b><small>{{formatTime(item.start_time)}} · {{roleName(item)}} · {{item.session_id||'无 session_id'}}</small></div><div class="turn-meta"><el-tag size="small" :type="item.status==='success'?'success':'danger'">{{statusLabel(item.status)}}</el-tag><span>{{duration(item.request_duration_ms)}}</span><span>{{number(item.total_tokens)}} tokens</span><el-button link type="primary" :loading="item._loading">弹窗查看详情</el-button></div></header>
                  <footer class="turn-footer"><span>请求 {{item.request_id||'未记录'}}</span><span>层级 {{item.depth||0}}</span><span>输入 {{number(item.prompt_tokens)}} / 输出 {{number(item.completion_tokens)}}</span><span>工具 {{number(item.tool_call_count)}}</span></footer>
                </article>
              </div>
              <el-empty v-else description="没有匹配的模型交互"/>
            </el-tab-pane>
            <el-tab-pane label="主 Agent / Subagent" name="sessions"><div class="session-tree"><article v-for="(node,index) in detail.sessions" :key="node.session_id" :style="{marginLeft:`${Math.min(node.depth,6)*28}px`}" @click="selectSessionNode(node)"><span class="tree-line">{{sessionNodeLabel(node,index)}}</span><div><b>{{node.session_id}}</b><small v-if="node.parent_session_id">父会话：{{node.parent_session_id}}</small><small>点击查看此 Agent 的全部模型交互</small></div><div class="tree-stats"><span>{{node.interaction_count}} 次调用</span><span>{{number(node.total_tokens)}} tokens</span><span>{{duration(node.duration_ms)}}</span><span>{{node.models?.join('、')||'模型未记录'}}</span></div></article></div></el-tab-pane>
            <el-tab-pane label="分析结果" name="analysis"><div v-loading="analysisDetailLoading" class="analysis-result"><template v-if="analysisDetail"><section><h3>任务分类</h3><el-descriptions :column="2" border><el-descriptions-item label="状态">{{analysisStatus(analysisDetail.component_statuses?.classification)}}</el-descriptions-item><el-descriptions-item label="分类">{{taskTypeLabel(analysisDetail.task_classification?.task_type)}}</el-descriptions-item><el-descriptions-item label="模型">{{analysisDetail.task_classification?.model||'未记录'}}</el-descriptions-item><el-descriptions-item label="理由">{{analysisDetail.task_classification?.reason||analysisDetail.task_classification?.error||'—'}}</el-descriptions-item></el-descriptions></section><section><h3>指标计算</h3><div class="result-metrics"><div v-for="item in metricResultCards" :key="item.label"><span>{{item.label}}</span><b>{{item.value}}</b></div></div><details><summary>查看指标完整 JSON</summary><pre>{{JSON.stringify({metrics:analysisDetail.metrics,quality_summary:analysisDetail.quality_summary},null,2)}}</pre></details></section><section><h3>会话 Judge</h3><el-descriptions :column="2" border><el-descriptions-item label="状态">{{analysisStatus(analysisDetail.component_statuses?.conversation_judge)}}</el-descriptions-item><el-descriptions-item label="模型">{{analysisDetail.judge?.models?.join('、')||analysisDetail.judge?.model||'未记录'}}</el-descriptions-item><el-descriptions-item label="分片">{{analysisDetail.judge?.chunks_completed||0}} / {{analysisDetail.judge?.chunks_total||0}}</el-descriptions-item><el-descriptions-item label="疑似伪造">{{analysisDetail.judge?.suspected_fabrications?.length||0}}</el-descriptions-item></el-descriptions><details><summary>查看会话 Judge 完整结果</summary><pre>{{JSON.stringify(analysisDetail.judge||{},null,2)}}</pre></details></section></template><el-empty v-else-if="!analysisDetailLoading" description="该会话尚无分析结果"/></div></el-tab-pane>
          </el-tabs>
        </template>
        <el-empty v-else-if="!detailLoading" description="没有读取到会话详情"/>
      </div>
    </el-dialog>
    <el-dialog v-model="processSessionVisible" width="88%" top="5vh" append-to-body destroy-on-close class="process-session-dialog">
      <template #header><div class="dialog-title"><div><span class="eyebrow">TASK SESSION PROCESS</span><b>{{taskKindLabel(analysisJob?.task_kind)}}处理详情</b><small>{{selectedProcessSession?.session_id}}</small></div><el-tag v-if="selectedProcessSession" :type="jobTag(selectedProcessSession.status)">{{jobStatus(selectedProcessSession.status)}}</el-tag></div></template>
      <template v-if="selectedProcessSession">
        <div class="process-session-facts"><div><span>Session ID</span><code>{{selectedProcessSession.session_id}}</code></div><div><span>Judge 模型</span><b>{{selectedProcessSession.assigned_model||'规则处理'}}</b></div><div><span>开始时间</span><b>{{formatTime(selectedProcessSession.started_at)}}</b></div><div><span>完成时间</span><b>{{formatTime(selectedProcessSession.finished_at)}}</b></div><div><span>用时</span><b>{{duration(selectedProcessSession.duration_ms)}}</b></div><div><span>处理步骤</span><b>{{selectedProcessSession.events?.length||0}}</b></div></div>
        <el-alert v-if="selectedProcessSession.error" :title="selectedProcessSession.error" type="error" :closable="false" show-icon/>
        <div class="saved-process process-session-events">
          <article v-for="event in selectedProcessSession.events||[]" :key="event.sequence"><i :class="event.outcome"/><div><b>{{event.message}}</b><small>{{event.stage}} · {{formatTime(event.timestamp)}}</small><pre v-if="event.input||event.output||event.interface||event.detail">{{JSON.stringify({input:event.input,output:event.output,interface:event.interface,detail:event.detail},null,2)}}</pre></div></article>
          <el-empty v-if="!selectedProcessSession.events?.length" description="该会话尚未产生处理步骤"/>
        </div>
        <section v-if="selectedProcessResult" class="process-final-result"><h3>最终处理结果</h3><pre>{{JSON.stringify(selectedProcessResult,null,2)}}</pre></section>
      </template>
    </el-dialog>
    <el-dialog v-model="savedProcessVisible" width="88%" top="5vh" append-to-body destroy-on-close><template #header><div class="dialog-title"><div><span class="eyebrow">ANALYSIS RESULT</span><b>{{taskKindLabel(savedProcess?.task_kind)}}结果</b><small>{{savedProcess?.session_id}}</small></div></div></template><div v-if="savedProcess?.task_kind==='classification'" class="classification-result"><section><h3>获取的 Prompt</h3><pre>{{savedProcess.prompt||'未获取到用户 Prompt'}}</pre></section><section><h3>分类结果</h3><pre>{{JSON.stringify(savedProcess.classification_result||{},null,2)}}</pre></section><section><h3>MongoDB 落库</h3><el-descriptions :column="2" border><el-descriptions-item label="是否成功"><el-tag :type="savedProcess.mongo_persisted?'success':'danger'">{{savedProcess.mongo_persisted?'成功':'失败'}}</el-tag></el-descriptions-item><el-descriptions-item label="Session ID">{{savedProcess.session_id}}</el-descriptions-item><el-descriptions-item label="checkType">{{savedProcess.check_type}}</el-descriptions-item><el-descriptions-item label="sessionType">{{savedProcess.session_type}}</el-descriptions-item></el-descriptions></section></div><div v-else class="saved-process"><article v-for="event in savedProcess?.events||[]" :key="event.sequence"><i :class="event.outcome"/><div><b>{{event.message}}</b><small>{{event.stage}} · {{formatTime(event.timestamp)}}</small><pre v-if="event.input||event.output||event.interface">{{JSON.stringify({input:event.input,output:event.output,interface:event.interface},null,2)}}</pre></div></article><el-empty v-if="!savedProcess?.events?.length" description="没有保存的过程事件"/></div></el-dialog>
    <InteractionDetailDialog v-model="interactionDialogVisible" :item="selectedInteraction" :turn-index="selectedInteractionIndex"/>
  </div>
</template>

<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {cancelMetricJob,createMetricJob,fetchMetricDetail,fetchMetricHealth,fetchMetricJob,fetchMetricJobs,fetchMetricProcess,fetchMetricQualityAggregate,fetchSchematicConversation,fetchSchematicConversations,fetchSchematicInteractionDetail,fetchSchematicInteractionFilters} from '../api'
